// Sunburst effect using scanlines and polar coordinates. Full tutorial here:
// https://agatedragon.blog/2025/01/16/sunburst-shader-tutorial/

// Math constants
const float PI = 3.14159265359;
const float TWO_PI = PI * 2.0;

// Colours
const vec3 COL1 = vec3(0.34, 0.58, 0.18);
const vec3 COL2 = vec3(0.28, 0.09, 0.44);

// Scanline constants
const float REPEAT = 30.0;
const float MOD_VALUE = 2.0;
const float ROTATION_SPEED = 0.02;

// GLSL atan2 function
// https://stackoverflow.com/questions/26070410/robust-atany-x-on-glsl-for-converting-xy-coordinate-to-angle
float atan2(in float y, in float x)
{
    bool s = (abs(x) > abs(y));
    return mix(PI/2.0 - atan(x,y), atan(y,x), s);
}

// Convert to polar coordinates
// https://www.ronja-tutorials.com/post/053-polar-coordinates/
vec2 ToPolar(vec2 cartesian)
{
	float len = length(cartesian);
	float angle = atan2(cartesian.y, cartesian.x);
	return vec2(angle / TWO_PI, len);
}

// Create scanlines
// https://agatedragon.blog/2024/01/26/shadertoy-scanline/
float Scanlines(float x, float repeat, float modValue)
{
    x = floor(x * repeat);
    return mod(x, modValue);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalised pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord / iResolution.xy;

    // Convert to polar coordinates
    vec2 pos = uv - 0.5;
    pos = ToPolar(pos);

    // Create scanlines
    float scanlines = Scanlines(pos.x + (iTime * ROTATION_SPEED), REPEAT, MOD_VALUE);

    // Change colour of the scanlines
    fragColor.rgb = mix(COL1, COL2, scanlines);
}
